import { boolean, integer, jsonb, pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core';

import { properties } from '../../properties/repo/properties.schema.ts';
import { users } from '../../users/repo/users.schema.ts';

/** Stored file variants (original kept; derivatives generated by sharp). */
export interface MediaRenditions {
  original: string;
  web?: string;
  thumb?: string;
  social?: string;
}

/**
 * Property (and later article) media assets — ADR-0010.
 * Storage keys are paths relative to the storage root; URLs are built by the adapter.
 */
export const mediaAssets = pgTable('media_assets', {
  id: uuid().defaultRandom().primaryKey(),
  propertyId: uuid()
    .notNull()
    .references(() => properties.id, { onDelete: 'cascade' }),
  /** image | video_link | tour_link | document | plan */
  kind: text().notNull().default('image'),
  /** public | internal | brochure */
  visibility: text().notNull().default('public'),
  mimeType: text().notNull(),
  byteSize: integer().notNull(),
  width: integer(),
  height: integer(),
  sortOrder: integer().notNull().default(0),
  isPrimary: boolean().notNull().default(false),
  altBg: text().notNull().default(''),
  altEn: text().notNull().default(''),
  captionBg: text().notNull().default(''),
  captionEn: text().notNull().default(''),
  /** External URL for video/tour kinds; null for uploaded files. */
  externalUrl: text(),
  renditions: jsonb().$type<MediaRenditions>().notNull(),
  uploadedByUserId: uuid().references(() => users.id),
  archivedAt: timestamp({ withTimezone: true }),
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});
